create or replace function compost_takes() returns text[] language sql immutable as $fn$ select array['mixed_grass', 'moss', 'ash', 'bone']::text[] $fn$;
create or replace function decor_said(p_key text, p_slot text) returns text language sql immutable as $fn$ select replace(case p_key when 'binFull' then 'Compost bin: full, 20 things.' when 'nothingToCompost' then 'Nothing to compost: food at 40% damage or more, mixed grass, moss, ashes or bone.' when 'binReady' then 'Compost ready: take it first.' when 'binEmpty' then 'Compost bin: empty.' when 'notReady' then 'Not ready: compost 2 days after the last thing went in.' when 'noCrop' then 'No crop there.' when 'noCompost' then 'Need 1 compost.' when 'fed' then 'Already composted: next harvest QL +10.' when 'rugFull' then 'Woven rug: 3 colours. Remove the dye first.' when 'notYours' then 'Not yours: armour stand.' when 'noArmour' then 'No armour in your pack for a free slot.' when 'notArmour' then 'Armour stand: armour only.' when 'slotTaken' then '{slot} slot taken.' when 'slotEmpty' then 'Nothing on that slot.' when 'nothingToSwap' then 'Nothing to swap: no armour on the stand or worn.' end, '{slot}', upper(left(coalesce(p_slot, ''), 1)) || substr(coalesce(p_slot, ''), 2)) $fn$;

select private.lock_doors();
